-- Class notes synopsis batch 14: Hops through Japanese Knotweed

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Hops</strong> is a <strong>cooling bitter</strong>, <strong>sedative nervine</strong>, and <strong>antispasmodic</strong>; its differential picture includes stress-induced <strong>stomach heat</strong>, over-planning, over-thinking, and <strong>menopausal sleep disturbances</strong>. A <strong>sedative</strong> for stress, pain, anxiety, and <strong>premenopausal insomnia</strong>; combined with <a href="?herb=145"><strong>Valerian</strong></a> for sleep encouragement - time sleep herbs between 5:00-7:00 PM; also a <strong>sedative/anodyne</strong> for influenza aches and pains. Topical <strong>analgesic</strong> for <strong>rheumatoid arthritis</strong>; noted in combination with <a href="?herb=1630"><strong>Teasel</strong></a> as a spray for <strong>neck pain</strong>. Used for <strong>upper GI excess</strong> with pain as an antispasmodic; a <strong>cooling bitter</strong> for <strong>hypochlorhydria</strong>. A <strong>phytoestrogen</strong> source - nourishes aging estrogen; supports apoptosis in <strong>fibrosis</strong>. Historically, Beer Hall laws employed by the Catholic Church turned people away from multi-herb knowledge toward hops alone. <strong>Estrogenic - avoid in breast cancer and endometriosis; also avoid Red Clover (also estrogenic) in the same contraindicated populations.</strong>$$
WHERE id = 129;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Horehound</strong> is a <strong>bitter</strong>, <strong>aromatic expectorant</strong> - its bitterness, noted as a key therapeutic quality in the African American Materia Medica, expels tough phlegm, regulates mucus secretion, loosens and thins mucus. Used in horehound candies, which are <strong>electuaries</strong> (powdered herbs bound with honey). Also indicated for <strong>viral and bacterial infection</strong>.$$
WHERE id = 160;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Horse Chestnut</strong> addresses the <strong>veins</strong> to bring fluid back up to the heart and is used for <strong>varicose veins</strong> - used alongside <a href="?herb=182"><strong>Stoneroot</strong></a> and <strong>Horsebalm</strong> for venous support.$$
WHERE id = 62;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Horseradish</strong> is a <strong>pungent</strong> herb.$$
WHERE id = 113;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Horsetail</strong> (Equisetum arvense) is a <strong>salty</strong>, <strong>astringent</strong>, <strong>diuretic</strong>, <strong>hemostatic</strong>, <strong>vulnerary</strong>, <strong>kidney tonic</strong>, and <strong>mineralizer</strong>; high in <strong>silica</strong>, supporting all silica-containing structures - bones, cartilage, hair, skin, nails, and mucous membranes; all collagen-containing structures benefit. A <strong>GI nutritive</strong>; best extracted in water or vinegar over long periods - spagyric process reincorporates minerals otherwise lost in alcohol extraction. Used in nourishing teas (2 parts) for <strong>bone density</strong> and nervous system support (long overnight infusion); in a repair blend with <a href="?herb=70"><strong>Calendula</strong></a> and <a href="?herb=85"><strong>Plantain</strong></a> for the chronic nourishing/moistening dimension of respiratory cases, supporting <strong>membrane integrity</strong>; and in a regenerative tea blend with <a href="?herb=95"><strong>Corn Silk</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, and <a href="?herb=42"><strong>Red Clover</strong></a>. Ingredient in "Sleepy Horsey" tea with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=13"><strong>Holy Basil</strong></a>, and <a href="?herb=82"><strong>Lavender</strong></a>. Astringent for <strong>urinary</strong> and <strong>reproductive health</strong> alongside <a href="?herb=148"><strong>Agrimony</strong></a>; a <strong>urinary diuretic</strong> that removes excess water and sodium. Substituted for <a href="?herb=155"><strong>Red Raspberry</strong></a> in Feri's infusion tea - gentle <strong>diaphoretic</strong> that gently opens pores for sweating and alleviates nighttime urination. For <strong>kidney deficiency</strong>: stimulates nephrons; for <strong>kidney excess</strong>: diuretic cooler (also noted for deficiency); for <strong>respiratory excess</strong>: cools overproduction.$$
WHERE id = 151;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Hyssop</strong> is a cleansing, purifying herb with deep roots in biblical ritual cleansing. Used for <strong>asthma</strong> as an <strong>anti-inflammatory</strong>. <strong>Caution: Hyssop essential oil and hydrosol can cause seizures - hazardous in those forms.</strong>$$
WHERE id = 53;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Irish Moss</strong> is a <strong>demulcent</strong> and <strong>pulmonary tonic</strong> - used for <strong>asthma</strong> and <strong>emphysema</strong> alongside <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a>, and <a href="?herb=78"><strong>Licorice</strong></a> (careful with high blood pressure). Also a <strong>bulk-building</strong> herb for <strong>childhood constipation</strong>.$$
WHERE id = 49;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Jamaican Dogwood</strong> ("Florida fish poison tree") is a <strong>hypnotic analgesic</strong> and <strong>sedative</strong> - decreases pain and increases quality of sleep; will not sedate an unwilling person. Specific for <strong>smooth muscle pain</strong>, <strong>nerve pain</strong>, <strong>phantom pains</strong> (amputations), face pain, <strong>tachycardia</strong>, and nervous irritability; an <strong>anodyne</strong> for general body pains and <strong>bone aches</strong> (flu) - lower dose plant, 10-15 drops for pain. For <strong>insomnia with spasms</strong> and <strong>pain-induced insomnia</strong>. Used in Lisa's sleep tincture with <a href="?herb=2624"><strong>Pedicularis</strong></a> and <a href="?herb=136"><strong>Catnip</strong></a> glycerite. Part of a TCM triplet with <a href="?herb=130"><strong>Wild Lettuce</strong></a> and <a href="?herb=2228"><strong>Corydalis</strong></a> for skeletal muscle injuries. For <strong>endometriosis</strong> pain. Pairs with <a href="?herb=87"><strong>Willow</strong></a> or <a href="?herb=75"><strong>Meadowsweet</strong></a> (anti-inflammatory) for pain; pairs with <a href="?herb=130"><strong>Wild Lettuce</strong></a> or <a href="?herb=138"><strong>Kava</strong></a> for recent injury; pairs with <a href="?herb=129"><strong>Hops</strong></a> or <a href="?herb=142"><strong>Skullcap</strong></a> for insomnia from body aches; pairs with <a href="?herb=25"><strong>Black Cohosh</strong></a> for skeletal pain. <strong>Anodynes can also be sedative - caution with driving.</strong>$$
WHERE id = 2461;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Japanese Honeysuckle</strong> is an <strong>antiviral</strong> herb that inhibits <strong>viral replication</strong>.$$
WHERE id = 2234;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Japanese Knotweed</strong> is part of Stephen Buhner's protocol for <strong>stealth-virus-related musculoskeletal pain</strong>, including <strong>long COVID</strong> - used alongside <a href="?herb=2274"><strong>Baical Skullcap</strong></a>, <strong>Salvia</strong>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=981"><strong>Red Root</strong></a>. In long COVID, respiratory cilia desiccate, tissues become overwhelmed with debris, <strong>mast cells</strong> lock down, and amyloid plaque enters the bloodstream - producing a chronically achy body; treatment focus is moistening tissues and clearing stagnation.$$
WHERE id = 2623;
